import numpy as np, time
import sim

L_HY, L_HR, L_HP, L_K, L_A = 0,1,2,3,4
R_HY, R_HR, R_HP, R_K, R_A = 5,6,7,8,9
TORSO = 10
kp = np.array([16, 16, 22, 26, 10, 16, 16, 22, 26, 10, 18, 8, 8, 6, 6, 8, 8, 6, 6], dtype=float)
kd = np.array([2.2, 2.2, 2.8, 3.2, 1.2, 2.2, 2.2, 2.8, 3.2, 1.2, 2.5, 1.2, 1.2, 0.8, 0.8, 1.2, 1.2, 0.8, 0.8], dtype=float)
max_torque = np.array([200,200,200,300,40,200,200,200,300,40,200,40,40,18,18,40,40,18,18], dtype=float)

def eval_sequence(poses, durations, settle=(0.0,0.0,0.0,0.0)):
    s=sim.Sim(); home=s.home_ctrl().copy()
    def act(qdes):
        q=s.data.qpos[7:7+19]; dq=s.data.qvel[6:6+19]
        s.data.ctrl[:] = np.clip(kp*(qdes-q)-kd*dq, -1, 1)*max_torque
    for _ in range(80):
        qdes=home.copy(); qdes[TORSO]=-0.1; act(qdes); s.step()
    xs=[]
    for pose, dur in zip(poses, durations):
        for t in range(dur):
            qdes=home.copy(); qdes[TORSO]=pose['torso']; qdes[L_HP]=pose['l_hp']; qdes[R_HP]=pose['r_hp']; qdes[L_K]=pose['l_k']; qdes[R_K]=pose['r_k']; qdes[L_A]=home[L_A]-0.12; qdes[R_A]=home[R_A]-0.12; qdes[L_HR]=pose.get('l_hr',0.0); qdes[R_HR]=pose.get('r_hr',0.0)
            act(qdes); s.step(); xs.append(s.pelvis_position()[0])
    p=s.pelvis_position(); mat=np.array(s.data.xmat[s.torso_body_id]).reshape(3,3); yaw=np.degrees(np.arctan2(mat[1,0], mat[0,0]))
    return {'x':float(p[0]),'y':float(p[1]),'z':float(p[2]),'yaw':float(yaw),'torso':float(s.torso_up()),'maxx':float(max(xs)), 'stable':float(np.mean([(e['pelvis_pos'][2] >= 0.23 and e['torso_up'] >= 0.55) for e in s._trace]))}

A={'torso':-0.2,'l_hp':-0.6,'l_k':0.2,'r_hp':-0.4,'r_k':0.8,'l_hr':0.0,'r_hr':0.0}
B={'torso':-0.2,'l_hp':-0.4,'l_k':0.8,'r_hp':-0.6,'r_k':0.2,'l_hr':0.0,'r_hr':0.0}
for name, seq in [('A', [A]), ('B',[B]), ('A+B',[A,B]), ('A+B+A',[A,B,A]), ('A*2',[A,A])]:
    durations = [350]*len(seq)
    t0=time.time(); r=eval_sequence(seq,durations); print(name, 'sec', round(time.time()-t0,2), r)
PY"

